    return { parseBody: pb, validatorForm: multipartRegex.test(ct) || urlencodedRegex.test(ct), validatorJson: jsonRegex.test(ct) }
  })
}
// 7. plain Request memory path: bodyUsed etc.
await show('plain Request parseBody', async () => parseBody(multipart()))
