import { Hono } from '$C/src/index'
import { HonoRequest } from '$C/src/request'
import { validator } from '$C/src/validator'
const mixed = async () => {
  const fd = new FormData(); fd.append('message', 'hello')
  const src = new Request('http://localhost/', { method: 'POST', body: fd })
  const ct = src.headers.get('Content-Type')!.replace('multipart/form-data', 'Multipart/Form-Data')
  return new Request('http://localhost/', { method: 'POST', body: await src.arrayBuffer(), headers: { 'Content-Type': ct } })
}
const show = async (l: string, f: () => Promise<unknown>) => { try { console.log(l, '=>', JSON.stringify(await f())) } catch (e) { console.log(l, '=> THROW', (e as Error).message) } }
await show('mixed multipart parseBody', async () => new HonoRequest(await mixed()).parseBody())
await show('mixed multipart validator(form)', async () => {
  const app = new Hono(); app.post('/', validator('form', (v) => v), (c) => c.json(c.req.valid('form')))
  const r = await app.request(await mixed()); return { status: r.status, body: await r.text() }
})
await show('malformed multipart validator(form)', async () => {
  const app = new Hono(); app.post('/', validator('form', (v) => v), (c) => c.json(c.req.valid('form')))
  const r = await app.request('/', { method: 'POST', body: 'garbage', headers: { 'Content-Type': 'multipart/form-data; boundary=x' } }); return { status: r.status, body: await r.text() }
})
await show('parseBody then text() round-trips original bytes', async () => {
  const src = await mixed(); const bytes = await src.clone().text()
  const req = new HonoRequest(src); await req.parseBody(); return (await req.text()) === bytes
})
EOF
